  1→import { useState, useRef, useEffect } from 'react';
  2→import ReactMarkdown from 'react-markdown';
  3→import remarkGfm from 'remark-gfm';
  4→import { useTranslation } from '../hooks/useTranslation';
  5→import type { ChatMessage, ContentSegment } from '../types';
  6→import { useAgent } from '../hooks/useAgent';
  7→import { InlineQueryResult } from './InlineQueryResult';
  8→import { ChartWidget } from './ChartWidget';
  9→import { UserQuestion } from './UserQuestion';
 10→import './MessageBubble.css';
 11→
 12→/**
 13→ * Strip chart_spec JSON code blocks from answer text.
 14→ * The orchestrator may include the raw chart spec JSON even though the chart
 15→ * is rendered separately. Remove ```json ... ``` blocks containing chart_spec
 16→ * or Plotly trace data so they don't appear as raw text.
 17→ */
 18→function stripChartSpecBlocks(text: string): string {
 19→  return text.replace(/```(?:json)?\s*\n?\s*\{[\s\S]*?"(?:chart_spec|data)"[\s\S]*?\}\s*\n?\s*```/g, '').trim();
 20→}
 21→
 22→function getLastThinkingLine(segments: ContentSegment[], streamingRemainder: string | undefined, t: (key: string) => string): string {
 23→  // Use streaming remainder if available
 24→  if (streamingRemainder?.trim()) {
 25→    const lines = streamingRemainder.trim().split('\n').filter((l) => l.trim());
 26→    const last = lines[lines.length - 1] || '';
 27→    return last.length > 100 ? last.slice(0, 100) + '...' : last;
 28→  }
 29→  // Otherwise use last thinking segment's last line
 30→  for (let i = segments.length - 1; i >= 0; i--) {
 31→    if (segments[i].type === 'thinking' && segments[i].text?.trim()) {
 32→      const lines = segments[i].text!.trim().split('\n').filter((l) => l.trim());
 33→      const last = lines[lines.length - 1] || '';
 34→      return last.length > 100 ? last.slice(0, 100) + '...' : last;
 35→    }
 36→  }
 37→  return t('thinking');
 38→}
 39→
 40→function ThinkingBlock({ segments, streamingRemainder, isThinkingPhase, isAgentStreaming, hasAnswer }: {
 41→  segments: ContentSegment[];
 42→  streamingRemainder?: string;
 43→  isThinkingPhase: boolean;
 44→  isAgentStreaming: boolean;
 45→  hasAnswer: boolean;
 46→}) {
 47→  const { t } = useTranslation();
 48→  // All non-answer, non-chart, non-user_question segments go inside the thinking block
 49→  // When hasAnswer is true, subagent_end text segments are shown here instead of in the answer block
 50→  const thinkingSegments = segments.filter(
 51→    (s) => s.type !== 'answer' && s.type !== 'user_question' && !(s.type === 'tool' && s.toolResult?.chart_spec) && !(s.type === 'subagent_end' && (s.chart_spec || (s.text?.trim() && !hasAnswer)))
 52→  );
 53→  const hasContent = thinkingSegments.some(
 54→    (s) => (s.type === 'thinking' && s.text?.trim()) || (s.type === 'tool' && s.toolResult) || s.type === 'subagent_start' || (s.type === 'subagent_end' && !s.chart_spec && s.text?.trim())
 55→  ) || streamingRemainder?.trim();
 56→
 57→  if (!hasContent) return null;
 58→
 59→  // Show preview only while agent is still working (hidden by CSS when collapsible is open anyway)
 60→  const summary = isAgentStreaming ? getLastThinkingLine(segments, streamingRemainder, t) : '';
 61→
 62→  return (
 63→    <details className="message-bubble__segment message-bubble__segment--thinking message-bubble__collapsible" open={isThinkingPhase || undefined}>
 64→      <summary className="message-bubble__collapsible-summary">
 65→        <span className="message-bubble__segment-label">{t('thinkingLabel')}</span>
 66→        {summary && <span className="message-bubble__collapsible-preview">{summary}</span>}
 67→      </summary>
 68→      <div className="message-bubble__thinking-body">
 69→        {thinkingSegments.map((seg, i) => {
 70→          if (seg.type === 'thinking' && seg.text?.trim()) {
 71→            return (
 72→              <div key={i} className="message-bubble__segment-content">
 73→                <ReactMarkdown remarkPlugins={[remarkGfm]}>{seg.text}</ReactMarkdown>
 74→              </div>
 75→            );
 76→          }
 77→          if (seg.type === 'tool' && seg.toolResult) {
 78→            return (
 79→              <div key={i} className="message-bubble__tool-segment">
 80→                <InlineQueryResult result={seg.toolResult} />
 81→              </div>
 82→            );
 83→          }
 84→          if (seg.type === 'subagent_start') {
 85→            const displayName = seg.subagentName === 'sql-analyst'
 86→              ? t('sqlAnalystWorking')
 87→              : `${seg.subagentName} working...`;
 88→            return (
 89→              <div key={i} className="message-bubble__subagent-indicator">
 90→                <span className="message-bubble__subagent-label">{displayName}</span>
 91→              </div>
 92→            );
 93→          }
 94→          if (seg.type === 'subagent_end' && !seg.chart_spec && seg.text?.trim()) {
 95→            return (
 96→              <div key={i} className="message-bubble__segment-content">
 97→                <ReactMarkdown remarkPlugins={[remarkGfm]}>{seg.text}</ReactMarkdown>
 98→              </div>
 99→            );
100→          }
101→          return null;
102→        })}
103→        {streamingRemainder?.trim() && (
104→          <div className="message-bubble__segment-content">
105→            <ReactMarkdown remarkPlugins={[remarkGfm]}>{streamingRemainder}</ReactMarkdown>
106→          </div>
107→        )}
108→      </div>
109→    </details>
110→  );
111→}
112→
113→function ErrorBlock({ errorMessage, onRetry }: { errorMessage: string; onRetry?: () => void }) {
114→  const { t } = useTranslation();
115→  return (
116→    <div className="message-bubble__segment message-bubble__segment--error">
117→      <div className="message-bubble__error-header">{t('errorOccurred')}</div>
118→      <div className="message-bubble__error-message">{errorMessage}</div>
119→      {onRetry && (
120→        <button className="message-bubble__error-retry" onClick={onRetry}>
121→          {t('tryAgain')}
122→        </button>
123→      )}
124→    </div>
125→  );
126→}
127→
128→export function MessageBubble({ message, messageIndex }: { message: ChatMessage; messageIndex: number }) {
129→  const { t } = useTranslation();
130→  const { isStreaming, editMessage, deleteMessage, sendMessage, messages } = useAgent();
131→  const [isEditing, setIsEditing] = useState(false);
132→  const [editText, setEditText] = useState(message.content);
133→  const [isConfirmingDelete, setIsConfirmingDelete] = useState(false);
134→  const textareaRef = useRef<HTMLTextAreaElement>(null);
135→
136→  const isUser = message.role === 'user';
137→  const hasSegments = !isUser && message.segments && message.segments.length > 0;
138→
139→  useEffect(() => {
140→    if (isEditing && textareaRef.current) {
141→      textareaRef.current.focus();
142→      textareaRef.current.selectionStart = textareaRef.current.value.length;
143→    }
144→  }, [isEditing]);
145→
146→  const handleEdit = () => {
147→    setEditText(message.content);
148→    setIsEditing(true);
149→    setIsConfirmingDelete(false);
150→  };
151→
152→  const handleCancelEdit = () => {
153→    setIsEditing(false);
154→    setEditText(message.content);
155→  };
156→
157→  const handleSaveEdit = () => {
158→    const trimmed = editText.trim();
159→    if (!trimmed || trimmed === message.content) {
160→      handleCancelEdit();
161→      return;
162→    }
163→    setIsEditing(false);
164→    editMessage(messageIndex, trimmed);
165→  };
166→
167→  const handleDeleteConfirm = () => {
168→    setIsConfirmingDelete(false);
169→    deleteMessage(messageIndex);
170→  };
171→
172→  const handleKeyDown = (e: React.KeyboardEvent) => {
173→    if (e.key === 'Escape') {
174→      handleCancelEdit();
175→    } else if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) {
176→      e.preventDefault();
177→      handleSaveEdit();
178→    }
179→  };
180→
181→  let streamingRemainder: string | undefined;
182→  if (hasSegments && message.isStreaming && message.content) {
183→    const segmentedText = message.segments!
184→      .filter((s) => s.type === 'thinking' || s.type === 'answer')
185→      .map((s) => s.text || '')
186→      .join('');
187→    const remaining = message.content.slice(segmentedText.length);
188→    if (remaining.trim()) {
189→      streamingRemainder = remaining;
190→    }
191→  }
192→
193→  const hasAnswer = !!hasSegments && message.segments!.some((s) => s.type === 'answer');
194→  const isInAnswerPhase = message.currentPhase === 'answer';
195→  const isThinkingPhase = !!message.isStreaming && !hasAnswer && !isInAnswerPhase;
196→
197→  const hasCharts = hasSegments && message.segments!.some(
198→    (s) => (s.type === 'tool' && s.toolResult?.chart_spec) || (s.type === 'subagent_end' && s.chart_spec)
199→  );
200→
201→  const answerBlockSegments = hasSegments
202→    ? message.segments!
203→        .filter((s) =>
204→          (s.type === 'answer' && s.text?.trim()) ||
205→          (s.type === 'subagent_end' && !s.chart_spec && s.text?.trim() && !hasAnswer) ||
206→          (s.type === 'tool' && s.toolResult?.chart_spec) ||
207→          (s.type === 'subagent_end' && s.chart_spec)
208→        )
209→        .map((s) => {
210→          if ((s.type === 'answer' || (s.type === 'subagent_end' && !s.chart_spec)) && s.text && hasCharts) {
211→            return { ...s, text: stripChartSpecBlocks(s.text) };
212→          }
213→          return s;
214→        })
215→        .filter((s) => {
216→          // Remove text segments that became empty after stripping chart blocks
217→          if ((s.type === 'answer' || (s.type === 'subagent_end' && !s.chart_spec)) && !s.text?.trim()) {
218→            return false;
219→          }
220→          return true;
221→        })
222→    : [];
223→
224→  const questionSegments = hasSegments
225→    ? message.segments!.filter((s) => s.type === 'user_question' && s.questionData)
226→    : [];
227→
228→  return (
229→    <div className={`message-bubble message-bubble--${message.role}`}>
230→      <div className="message-bubble__header">
231→        {isUser ? t('you') : t('assistant')}
232→        {isUser && !isStreaming && !isEditing && !isConfirmingDelete && (
233→          <span className="message-bubble__actions">
234→            <button
235→              className="message-bubble__action-btn"
236→              onClick={handleEdit}
237→              title={t('editMessage')}
238→            >
239→              &#9998;
240→            </button>
241→            <button
242→              className="message-bubble__action-btn message-bubble__action-btn--delete"
243→              onClick={() => setIsConfirmingDelete(true)}
244→              title={t('deleteMessage')}
245→            >
246→              &#128465;
247→            </button>
248→          </span>
249→        )}
250→      </div>
251→
252→      {isUser && isConfirmingDelete && (
253→        <div className="message-bubble__confirm-delete">
254→          <span>{t('deleteConfirm')}</span>
255→          <div className="message-bubble__confirm-actions">
256→            <button
257→              className="message-bubble__confirm-btn message-bubble__confirm-btn--delete"
258→              onClick={handleDeleteConfirm}
259→            >
260→              {t('delete')}
261→            </button>
262→            <button
263→              className="message-bubble__confirm-btn"
264→              onClick={() => setIsConfirmingDelete(false)}
265→            >
266→              {t('cancel')}
267→            </button>
268→          </div>
269→        </div>
270→      )}
271→
272→      {isUser && isEditing ? (
273→        <div className="message-bubble__edit-mode">
274→          <textarea
275→            ref={textareaRef}
276→            className="message-bubble__edit-textarea"
277→            value={editText}
278→            onChange={(e) => setEditText(e.target.value)}
279→            onKeyDown={handleKeyDown}
280→            rows={3}
281→          />
282→          <div className="message-bubble__edit-actions">
283→            <button
284→              className="message-bubble__edit-btn message-bubble__edit-btn--save"
285→              onClick={handleSaveEdit}
286→            >
287→              {t('saveResend')}
288→            </button>
289→            <button
290→              className="message-bubble__edit-btn"
291→              onClick={handleCancelEdit}
292→            >
293→              {t('cancel')}
294→            </button>
295→          </div>
296→        </div>
297→      ) : hasSegments ? (
298→        <div className="message-bubble__segments">
299→          {!questionSegments.some((s) => !s.userAnswer) && (
300→            <ThinkingBlock
301→              segments={message.segments!}
302→              streamingRemainder={isThinkingPhase ? streamingRemainder : undefined}
303→              isThinkingPhase={isThinkingPhase}
304→              isAgentStreaming={!!message.isStreaming}
305→              hasAnswer={hasAnswer}
306→            />
307→          )}
308→          {questionSegments.map((seg, i) => (
309→            <div key={`question-${i}`} className="message-bubble__segment message-bubble__segment--question">
310→              <UserQuestion
311→                questionData={seg.questionData!}
312→                userAnswer={seg.userAnswer}
313→                userFreeText={seg.userFreeText}
314→              />
315→            </div>
316→          ))}
317→          {answerBlockSegments.length > 0 && (
318→            <div className="message-bubble__segment message-bubble__segment--answer">
319→              <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
320→              {answerBlockSegments.map((seg, i) => {
321→                // Chart segment (tool with chart_spec or subagent_end with chart_spec)
322→                if ((seg.type === 'tool' && seg.toolResult?.chart_spec) || (seg.type === 'subagent_end' && seg.chart_spec)) {
323→                  return (
324→                    <div key={`chart-${i}`} className="message-bubble__chart-in-answer">
325→                      {seg.type === 'tool' && seg.toolResult ? (
326→                        <InlineQueryResult result={seg.toolResult!} />
327→                      ) : seg.chart_spec ? (
328→                        <ChartWidget data={seg.chart_spec.data} layout={seg.chart_spec.layout} frames={seg.chart_spec.frames} />
329→                      ) : null}
330→                    </div>
331→                  );
332→                }
333→                // Text segment (answer or subagent_end without chart_spec)
334→                return (
335→                  <div key={`answer-${i}`} className="message-bubble__segment-content">
336→                    <ReactMarkdown remarkPlugins={[remarkGfm]}>{seg.text!}</ReactMarkdown>
337→                  </div>
338→                );
339→              })}
340→              {/* Render streaming remainder inside the same answer block to avoid duplicate headers */}
341→              {isInAnswerPhase && streamingRemainder?.trim() && (() => {
342→                const displayText = hasCharts ? stripChartSpecBlocks(streamingRemainder) : streamingRemainder;
343→                return displayText?.trim() ? (
344→                  <div className="message-bubble__segment-content">
345→                    <ReactMarkdown remarkPlugins={[remarkGfm]}>{displayText}</ReactMarkdown>
346→                  </div>
347→                ) : null;
348→              })()}
349→            </div>
350→          )}
351→          {/* Only show standalone streaming answer block when no answer segments exist yet */}
352→          {answerBlockSegments.length === 0 && isInAnswerPhase && streamingRemainder?.trim() && (() => {
353→            const displayText = hasCharts ? stripChartSpecBlocks(streamingRemainder) : streamingRemainder;
354→            return displayText?.trim() ? (
355→              <div className="message-bubble__segment message-bubble__segment--answer">
356→                <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
357→                <div className="message-bubble__segment-content">
358→                  <ReactMarkdown remarkPlugins={[remarkGfm]}>{displayText}</ReactMarkdown>
359→                </div>
360→              </div>
361→            ) : null;
362→          })()}
363→          {message.segments!.filter((s) => s.type === 'error').map((seg, i) => {
364→            const lastUserMsg = messages.slice().reverse().find((m) => m.role === 'user');
365→            const handleRetry = lastUserMsg ? () => sendMessage(lastUserMsg.content) : undefined;
366→            return <ErrorBlock key={`error-${i}`} errorMessage={seg.errorMessage || 'Unknown error'} onRetry={!isStreaming ? handleRetry : undefined} />;
367→          })}
368→          {message.isStreaming && !message.content && questionSegments.length === 0 && (
369→            <span className="message-bubble__typing">{t('thinking')}</span>
370→          )}
371→        </div>
372→      ) : (
373→        <>
374→          <div className="message-bubble__content">
375→            {message.content ? (
376→              <ReactMarkdown remarkPlugins={[remarkGfm]}>{message.content}</ReactMarkdown>
377→            ) : message.isStreaming ? (
378→              <span className="message-bubble__typing">{t('thinking')}</span>
379→            ) : null}
380→          </div>
381→          {message.toolCalls && message.toolCalls.length > 0 && (
382→            <div className="message-bubble__tools">
383→              {message.toolCalls.map((tc) => (
384→                <InlineQueryResult key={tc.toolCallId} result={tc} />
385→              ))}
386→            </div>
387→          )}
388→        </>
389→      )}
390→    </div>
391→  );
392→}
